  dev: 16777220,
  mode: 33188,
  nlink: 1,
  uid: 501,
  gid: 20,
  rdev: 0,
  blksize: 4096,
  ino: 8648323536,
  size: 31,
  blocks: 8,
  atimeMs: 1700671481153.5369,
  mtimeMs: 1700667050455.9146,
  ctimeMs: 1700667050455.9146,
  birthtimeMs: 1643908248703.2,
