  ctime: 2023-11-22T15:30:50.456Z,
  birthtime: 2022-02-03T17:10:48.703Z
}
c:\app>
```



Для синхронного получения статистики применяется метод **statSync()**, который получает путь к файлу и возвращает объект статистики:



```javascript

const fs = require("fs");

const stats = fs.statSync("hello2.txt")
console.log(stats.isFile());        // true  
console.log(stats.isDirectory());   // false  
console.log(stats);
```



### Удаление файла



Для удаления файла в синхронном варианте используется функция **fs.unlinkSync()**, которая в качестве параметра принимает путь к удаляемому файлу:



```javascript
fs.unlinkSync("hello.txt")
```



Также для удаления файла можно использовать асинхронную функцию **fs.unlink()**, которая принимает путь к файлу и функцию, вызываемую при завершении удаления:



```javascript

fs.unlink("hello.txt", (error) => {
  if (error) return console.log(error); // если возникла ошибка	
  console.log("File deleted");
});
```



### Работа с каталогами



Также для работы с каталогами Node.js предоставляет ряд функций.



Для создания каталога применяется функции **mkdir()** (асинхронная) и **mkdirSync()** (синхронная). В качестве параметра они принимают название каталога. Асинхронный вариант в качестве второго параметра принимает функцию обратного вызова, которая срабатывает при создании каталога:



```javascript

const fs = require("fs");

fs.mkdir("test", (error) => {  
        if (error) return console.log(error);
        console.log("Folder created");
});
```



Для считывания файлов из каталога применются функции **readdir()** (асинхронная) и **readdirSync()** (синхронная). В качестве параметра они принимают название каталога. Асинхронный вариант в качестве второго параметра принимает функцию обратного вызова, у которой второй параметр представляет список файлов и папок каталога:



```javascript

const fs = require("fs");

fs.readdir("test", (error, files) => {  
        if (error) return console.log(error);
        files.forEach((file) => console.log(file));
});
```



Для удаления каталога применяются функции **rmdir()** (асинхронная) и **rmdirSync()**. В качестве параметра они принимают название каталога. Асинхронный вариант в качестве второго параметра принимает функцию обратного вызова, которая срабатывает при удалении каталога:



```javascript

const fs = require("fs");

fs.rmdir("test", (error) => {  
        if (error) return console.log(error);
        console.log("Folder deleted");
});
```

Множество функционала Node.js применяет асинхронную событийную архитектуру, где различные действия выполняются в ответ на возникшие события. В подобной архитектуре сначала специальные объекты, которые называются **эмиттерами событий** (event emitter), генерируют события. Затем специальные функции - обработчики или слушатели событий обрабатывают возникшее событие.

### Генерация события и тип EventEmitter

Итак, для генерации событий нам нажем эмиттер событий. Эмиттер событий представляет объекты типа **EventEmitter**. Данный тип определен в модуле "events":

```javascript
const EventEmitter = require("events");
// определяем эмиттер событий
const emitter = new EventEmitter();
```

EventEmitter предоставляет ряд методов для управления обработчиками событий:

- `on (eventName, listener)` : псевдоним метода on(). Регистрирует новый слушатель listener для события eventName.

- `addListener(eventName, listener)` : псевдоним метода on(). Регистрирует новый слушатель listener сдля события eventName.

- `emit(eventName [, args])` : запускает событие. В качестве обязательного параметра принимает имя события. Также дополнительно можно передать необязательный параметр - аргументы для обработчика события

- `eventNames()` : возвращает массив с именами событий, для которых зарегистрированы слушатели

- `getMaxListeners()` : возвращает максимальное количество слушателей для данного эмиттера событий.

- `listenerCount(eventName)` : возвращает количество слушателей события eventName

- `listeners(eventName)` : возвращает массив со слушателями события eventName.

- `once(eventName, listener)` : регистрирует новый слушатель listener для события eventName, но выполняет его не более одного раза.

- `prependListener(eventName, listener)` : регистрирует новый слушатель listener для события eventName и помещает его в начало массива слушателей события eventName.

- `prependOnceListener(eventName, listener)` : аналогичен prependListener() за тем исключением, что слушатель listener вызывается не более одного раза.

- `removeAllListeners([eventName])` : удаляет всех слушателей события eventName

- `removeListener(eventName, listener)` : удаляет слушателя listener для события eventName.

- `setMaxListeners (п)` : устанавливает максимальное количество слушателей событий, которые можно зарегистрировать для каждого события в эмиттере событий

### Запуск и обработка события

Итак, для генерации события у `EventEmitter` надо вызвать метод **emit()**, в который передается имя события. Такб определим в файле **app.js** следующий код:

```javascript
const EventEmitter = require("events");
// определяем эмиттер событий
const emitter = new EventEmitter();

// имя события, которое будет обрабатываться
const eventName = "greet";
// генерируем событие greet
emitter.emit(eventName);
```

Здесь генерируется событие "greet". Названия событий произвольные.

Однако в ответ на это событие ничего не произойдет, событие пока никак не обрабатывается. Для регистрации обработчика события применяется метод **on()**, в который передается имя события и функция обработчика. Обработаем событие "greet":

```javascript
const EventEmitter = require("events");
// определяем эмиттер событий
const emitter = new EventEmitter();

// имя события, которое будет обрабатываться
const eventName = "greet";

// регистрируем обработчик для события "greet"
emitter.on(eventName, function(){
    console.log("Hello World!");
});

// генерируем событие greet
emitter.emit(eventName);
```

Здесь в качестве обработчика применяется функция, которая выводит строку "Hello World!" на консоль.

Запустим приложение:

```bash
c:\app> node app.js
Hello World!
c:\app>
```

Можно установить несколько обработчиков на одно событие:

```javascript
const EventEmitter = require("events");
// определяем эмиттер событий
const emitter = new EventEmitter();

// имя события, которое будет обрабатываться
const eventName = "greet";

// регистрируем три обработчика для события "greet"
emitter.on(eventName, function(){
    console.log("Hello World!");
});
emitter.on(eventName, function(){
    console.log("Привет мир!");
});
emitter.on(eventName, function(){
    console.log("Hallo Welt!");
});

// генерируем событие greet
emitter.emit(eventName);
```

В итоге при генерации события будут выполняться сразу три обработчика:

```bash
c:\app> node app.js
Hello World!
Привет мир!
Hallo Welt!
c:\app>
```

### Передача параметров событию

При вызове события в качестве второго параметра в метод **emit()** можно передавать некоторый объект, который передается в функцию обработчика события:

```javascript
const EventEmitter = require("events");
const emitter = new EventEmitter();

const eventName = "greet";

emitter.on(eventName, function(data){
	console.log(data);
});

emitter.emit(eventName, "Привет пир!");
```

### Наследование от EventEmitter

В приложении мы можем оперировать сложными объектами, для которых также можно определять события, но для этого их надо связать с объектом EventEmitter. Например:

```javascript
const EventEmitter = require("events");

const eventName = "greet";

emitter.on(eventName, function(data){
    console.log(data);
});

class User extends EventEmitter {
    constructor(username){
        super();    // вызываем конструктор EventEmitter
        this.name = username;
    }
    sayHi() {
        console.log("Привет. Меня зовут", this.name);
	this.emit(eventName, this.name);    // генерируем событие, передаем обработчику имя
    }
}

const tom = new User("Tom");
// добавляем к объекту tom обработку события "greet"
// обработчик ожидает получить через параметр имя пользователя
tom.on(eventName, function(username){
    console.log("Привет,", username);
});
// при выполнении метода генерируется событие "greet"
tom.sayHi();
```

Здесь определен класс User, который наследуется от типа EventEmitter. Через конструктор класс User получает имя пользователя. В классе User определен метод sayHi, в котором генерируется событие "greet", а обработчику событий передается имя пользователя.

Поскольку User унаследован от EventEmitter, то объекты User также имеют метод `on()`, через который можно установить обработчик события. Этот обработчик будет вызван при выполнении метода `sayHi()`.

Пример работы программы:

```bash
c:\app> node app.js
Привет. Меня зовут Tom
Привет, Tom
c:\app>
```

В качестве альтернативы наследованию можно передавать в объект объект EventEmitter:

```javascript
const EventEmitter = require("events");
const emitter = new EventEmitter();

const eventName = "greet";

emitter.on(eventName, function(username){
    console.log("Прив", username);
});

class User{
    constructor(username, emitter){
        this.name = username;
        this.emitter = emitter;
    }
    sayHi() {
        console.log("Привет. Меня зовут", this.name);
	this.emitter.emit(eventName, this.name);    // генерируем событие, передаем обработчику имя
    }
}

const tom = new User("Tom", emitter);
tom.sayHi();
```

Stream представляет поток данных. Потоки бывают различных типов, среди которых можно выделить [потоки для чтения](https://nodejs.org/api/stream.html#stream_readable_streams) и [потоки для записи](https://nodejs.org/api/stream.html#stream_writable_streams).

При создании сервера в первой главе мы уже сталкивались с потоками:

```javascript
const http = require("http");

http.createServer(function(request, response){

}).listen(3000);
```

Параметры request и response, которые передаются в функцию и с помощью которых мы можем получать данные о запросе и управлять ответом, как раз представляют собой потоки: request - поток для чтения, а response - поток для записи.

Используя потоки чтения и записи, мы можем считывать и записывать информацию в файл. Например:

```javascript
const fs = require("fs");

const writeableStream = fs.createWriteStream("hello.txt");
writeableStream.write("Привет мир!\n");
writeableStream.write("Продолжение записи\n");
writeableStream.end("Завершение записи\n");

const readableStream = fs.createReadStream("hello.txt");

readableStream.on("data", function(chunk){ 
    console.log(chunk.toString());
});
```

Для создания потока для записи применяется метод **fs.createWriteStream()**, в который передается название файла. Если вдруг в папке нет такого файла, то он создается.

Запись данных производится с помощью метода `write()`, в который передаются данные. Для окончания записи вызывается метод `end()`.

После этого в папке проекта появляется файл hello.txt, который можно открыть в любом текстовом редакторе.

Для создания потока для чтения используется метод **fs.createReadStream()**, в который также передается название файла. В качестве опционального параметра здесь передается кодировка, что позволит сразу при чтении кодировать считанные данные в строку в указанной кодировке.

Сам поток разбивается на ряд кусков или чанков (chunk). И при считывании каждого такого куска, возникает событие **data**. С помощью метода **on()** мы можем подписаться на это событие и вывести каждый кусок данных на консоль:

```javascript
readableStream.on("data", function(chunk){ 
	console.log(chunk.toString());
});
```

Запустим файл на выполнение:

```bash
c:\app> node app.js
Привет мир!
Продолжение записи
Завершение записи

c:\app>
```

Только работой с файлами функциональность потоков не ограничивается, также имеются сетевые потоки, потоки шифрования, архивации и т.д., но общие принципы работы с ними будут те же, что и у файловых потоков.

Pipe - это канал, который связывает поток для чтения и поток для записи и позволяет сразу считать из потока чтения в поток записи. Для чего они нужны? Возьмем, к примеру проблему копирования данных из одного файла в другой.

Пусть в папке проекта определен некоторый файл hello.txt . Скопируем его содержимое в новый файл some.txt :

```javascript
const fs = require("fs");

const readableStream = fs.createReadStream("hello.txt");

const writeableStream = fs.createWriteStream("some.txt");

readableStream.on("data", function(chunk){
    writeableStream.write(chunk);
});
```

Данный код вполне работоспособен, и после запуска файла в папке проекта появится новый файл some.txt.

Однако задача записи в поток данных, считанных из другого потока, является довольно распространенной, и в этом случае pipes или каналы позволяют нам сократить объем кода:

```javascript
const fs = require("fs");

const readableStream = fs.createReadStream("hello.txt");

const writeableStream = fs.createWriteStream("some2.txt");

readableStream.pipe(writeableStream);
```

У потока чтения вызывается метод **pipe()**, в который передается поток для записи.

Рассмотрим другую проблему - архивацию файла. Здесь нам надо сначала считать файл, затем сжать данные и в конце записать сжатые данные в файл-архив. Pipes особенно удобно применять для подобного набора операций:

```javascript
const fs = require("fs");
const zlib = require("zlib");

const readableStream = fs.createReadStream("hello.txt");

const writeableStream = fs.createWriteStream("hello.txt.gz");

const gzip = zlib.createGzip();

readableStream.pipe(gzip).pipe(writeableStream);
```

Для архивации подключается модуль **zlib**. Каждый метод pipe() в цепочке вызовов возвращает поток для чтения, к которому опять же можно применить метод pipe() для записи в другой поток.

Для работы с сервером и протоколом http в Node.js используется модуль [http](https://nodejs.org/api/http.html).



Чтобы создать сервер, следует вызвать метод `http.createServer()`:



```javascript

const http = require("http");

const server = http.createServer();
```



Метод `createServer()` возвращает объект `http.Server`. Для обработки подключений в метод createServer передается функция-обработчик:



```javascript

const http = require("http");

const server =  http.createServer(function(request, response){
	response.end("Hello enoobis.ru!");
});
```



Эта функция принимает два параметра:





- request : хранит информацию о запросе

- response : управляет отправкой ответа



В примере выше с помощью метода `response.end()` в ответ клиенту посылается строка "Hello enoobis.ru!".



Но чтобы сервер мог прослушивать и обрабатывать входящие подключения, у объекта сервера необходимо вызвать метод **listen()**. Данный метод может принимать различный набор параметров. Но обычно в качестве первого параметра передается номер порта, по которому запускается сервер.



```javascript

const http = require("http");

const server =  http.createServer(function(request, response){
	response.end("Hello enoobis.ru!");
});
server.listen(3000);
```



В данном случае сервер запускается по адресу 3000. Также дополнительно можно передать в метод listen функцию, которая будет срабатывать при запуске сервера:



```javascript

const http = require("http");

const server =  http.createServer(function(request, response){
	response.end("Hello enoobis.ru!");
});
server.listen(3000, function(){ console.log("Сервер запущен по адресу http://localhost:3000")});
```



Например, запустим приложение, и после успешного запуска мы увидим на консоли соответствующее сообщение:



```bash

c:\app> node app.js
Сервер запущен по адресу http://localhost:3000
```



Поскольку сервер запущен на порту 3000, то мы можем обратиться к нашему приложению в браузере по адресу `http://localhost:`**3000**



![создание сервера на node.js](/uploads/course-lectures/70fc4eb5c22429e4176057c2e5c86e0e76466eef.png)



### Request



Параметр request позволяет получить информацию о запросе и представляет объект **http.IncomingMessage**. Отметим некоторые основные свойства этого объекта:





- headers : возвращает заголовки запроса

- method : тип запроса (GET, POST, DELETE, PUT)

- url : представляет запрошенный адрес



Например, определим следующий файл app.js:



```javascript

const http = require("http");

http.createServer(function(request, response){
	
	console.log("Url:", request.url);
	console.log("Тип запроса:", request.method);
	console.log("User-Agent:", request.headers["user-agent"]);
	console.log("Все заголовки");
	console.log(request.headers);
	
	response.end();
}).listen(3000, function(){ console.log("Сервер запущен по адресу http://localhost:3000")});
```



Запустим его и обратимся в браузере по адресу http://localhost:3000/ , и консоль выведет нам информацию о запросе:



