		const db = mongoClient.db("usersdb");
		const collection = db.collection("users");
		const result = await collection.findOneAndDelete({age: 21});
		console.log(result);

	}catch(err) {
		console.log(err);
	} finally {
		await mongoClient.close();
	}
}
run().catch(console.error);
```

